import sys
input = sys.stdin.read

def is_lucky_ticket(n, ticket):
    total_sum = sum(ticket)

    # Try every possible segment sum from 1 to total_sum / 2
    for s in range(1, total_sum // 2 + 1):
        current_sum = 0
        possible = True

        for digit in ticket:
            current_sum += digit
            if current_sum == s:
                current_sum = 0
            elif current_sum > s:
                possible = False
                break

        if possible and current_sum == 0:
            return "YES"

    return "NO"

def main():
    data = input().split()
    n = int(data[0])
    ticket = [int(char) for char in data[1]]

    result = is_lucky_ticket(n, ticket)
    print(result)

if __name__ == "__main__":
    main()

