import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
ticket = data[1]

prefix_sum = [0] * (n + 1)
for i in range(n):
    prefix_sum[i + 1] = prefix_sum[i] + int(ticket[i])

dp = [[False] * (prefix_sum[-1] + 1) for _ in range(n + 1)]
dp[0][0] = True

for i in range(1, n + 1):
    for j in range(prefix_sum[-1] + 1):
        if j - int(ticket[i - 1]) >= 0:
            dp[i][j] |= dp[i - 1][j - int(ticket[i - 1])]
        dp[i][j] |= dp[i - 1][j]

if prefix_sum[-1] % 2 == 0 and dp[n][prefix_sum[-1] // 2]:
    print("YES")
else:
    print("NO")

